<script setup>
import BusyFeedback from './BusyFeedback.vue';
import {ref,computed,onMounted} from 'vue';import {api} from './api';import QuestionContent from './QuestionContent.vue';import MathText from './MathText.vue';
const props=defineProps({questionId:Number,reportId:Number});const emit=defineEmits(['close','saved']);
const sourcePage=ref(1);
const form=ref(null),history=ref([]),version=ref(null),baseline=ref(''),busy=ref(false),action=ref(''),error=ref(''),message=ref(''),image=ref(null),imageOption=ref('');
const dirty=computed(()=>form.value&&JSON.stringify(form.value)!==baseline.value);
const parsedAnswers=computed(()=>{try{return JSON.parse(form.value?.answerJSON||'null')}catch{return null}});
const previewImages=computed(()=>form.value?.images.filter(i=>form.value.image_ids.includes(i.id))||[]);
async function load(){const d=await api('/admin/questions/'+props.questionId);version.value=d.updated_at;history.value=d.history;sourcePage.value=d.question.source_page||1;form.value={...d.question,passage:d.question.passage||'',options:d.question.options.map(o=>({...o})),answerJSON:JSON.stringify(d.question.answers??null),image_ids:d.question.images.map(i=>i.id)};baseline.value=JSON.stringify(form.value)}
async function run(fn,label='Loading editor…'){if(busy.value)return;busy.value=true;action.value=label;error.value='';message.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false;action.value=''}}
onMounted(()=>run(load));
async function save(resolve=false){await run(async()=>{let answers;try{answers=JSON.parse(form.value.answerJSON)}catch{throw Error('Answer must be valid JSON, for example ["A"], 2.5 or null.')}
 await api('/admin/questions/'+props.questionId,{method:'PATCH',body:{updated_at:version.value,kind:form.value.kind,text:form.value.text,passage:form.value.passage,options:form.value.options,answers,marks:form.value.marks===''?null:form.value.marks,negative_marks:form.value.negative_marks===''?null:form.value.negative_marks,tolerance:form.value.tolerance===''?0:form.value.tolerance,explanation:form.value.explanation,topic:form.value.topic,image_ids:form.value.image_ids,...(resolve&&props.reportId?{resolve_report_id:props.reportId}:{})}});await load();emit('saved');message.value=resolve?'Correction saved and report resolved.':'Correction saved.'},resolve?'Saving and resolving report…':'Saving correction…')}
async function visibility(){await run(async()=>{await api('/admin/questions/'+props.questionId+'/visibility',{method:'POST',body:{updated_at:version.value,hidden:!form.value.hidden}});await load();emit('saved');message.value=form.value.hidden?'Question hidden from new attempts.':'Question restored.'},'Updating visibility…')}
async function undo(){if(dirty.value||!confirm('Undo the latest saved change?'))return;await run(async()=>{await api('/admin/questions/'+props.questionId+'/undo',{method:'POST',body:{updated_at:version.value}});await load();emit('saved');message.value='Latest change undone.'},'Undoing latest change…')}
async function uploadImage(){await run(async()=>{if(!image.value)throw Error('Choose an image.');const data=new FormData();data.append('file',image.value);data.append('updated_at',String(version.value));data.append('option_key',imageOption.value);await api('/admin/questions/'+props.questionId+'/images',{method:'POST',form:data});await load();emit('saved');message.value='Image added. Uncheck the old image and save to replace it.';image.value=null},'Uploading image…')}
function close(){if(!busy.value&&(!dirty.value||confirm('Discard unsaved changes?')))emit('close')}
</script>
<template><div class="modal-backdrop-custom"><section class="content-editor panel" role="dialog" aria-modal="true" aria-labelledby="edit-question-title" @keydown.esc.stop="close"><div class="section-row"><h2 id="edit-question-title">Edit question {{form?.number}}</h2><button class="btn btn-light" :disabled="busy" @click="close">Close</button></div><p v-if="error" class="alert alert-danger" role="alert">{{error}}</p><p v-if="message" class="alert alert-success" role="status">{{message}}</p><div v-if="busy" class="request-feedback" aria-busy="true"><BusyFeedback :label="action"/></div><template v-if="form"><p class="muted small">{{form.status}} · Manual corrections are protected from automatic reprocessing. Current attempts keep their original snapshots.</p><div class="editor-columns"><div><form @submit.prevent="save()"><label>Question type<select class="form-select" v-model="form.kind"><option v-for="kind in ['MCQ','MSQ','NAT','TRUE_FALSE','SHORT_TEXT','SUBJECTIVE','CODE','IMAGE']">{{kind}}</option></select></label><label>Shared passage (optional)<textarea class="form-control" rows="3" v-model="form.passage"></textarea></label><label>Question text / formulas<textarea class="form-control" rows="6" v-model="form.text" maxlength="20000"></textarea><small>Use **bold text** for emphasis, \(x^2\) for inline math and [[IMAGE:token]] to place an existing image.</small></label><label>Options</label><div class="edit-option" v-for="(o,n) in form.options" :key="n"><input class="form-control" v-model="o.key" aria-label="Option key" maxlength="20"><textarea class="form-control" v-model="o.text" aria-label="Option text" rows="2"></textarea><button type="button" class="btn btn-light" @click="form.options.splice(n,1)">Remove</button></div><button type="button" class="btn btn-light btn-sm" @click="form.options.push({key:String.fromCharCode(65+form.options.length),text:''})">Add option</button><label>Correct answer (JSON)<input class="form-control" v-model="form.answerJSON"><small>MCQ: ["A"] · MSQ: ["A","B"] · NAT: 2.5 · Unknown: null</small></label><div class="form-grid"><label>Marks<input class="form-control" type="number" min="0" step="any" v-model.number="form.marks"></label><label>Negative marks<input class="form-control" type="number" min="0" step="any" v-model.number="form.negative_marks"></label><label>NAT tolerance<input class="form-control" type="number" min="0" step="any" v-model.number="form.tolerance"></label><label>Topic<input class="form-control" v-model="form.topic" maxlength="150"></label></div><label>Explanation<textarea class="form-control" v-model="form.explanation" rows="3"></textarea></label><label v-for="i in form.images" :key="i.id" class="image-selection"><input type="checkbox" :value="i.id" v-model="form.image_ids"> Keep image {{i.token}} {{i.option_key?'· Option '+i.option_key:''}}<img :src="'/api/images/'+i.id" :alt="i.alt" class="question-image"></label><div class="dialog-actions"><button class="btn btn-primary" :disabled="busy"><BusyFeedback v-if="busy&&action==='Saving correction…'" :label="action"/><template v-else>Save correction</template></button><button v-if="reportId" type="button" class="btn btn-outline-primary" :disabled="busy" @click="save(true)">Save &amp; resolve report</button></div></form><details class="mt-3"><summary>Add / replace image</summary><p class="small muted">Save text changes first. Add a PNG/JPEG, then uncheck the old image and save.</p><input type="file" accept="image/png,image/jpeg" class="form-control" @change="image=$event.target.files[0]"><label>Image belongs to<select v-model="imageOption" class="form-select"><option value="">Question / passage</option><option v-for="o in form.options" :value="o.key">Option {{o.key}}</option></select></label><button class="btn btn-light mt-2" :disabled="busy||dirty||!image" @click="uploadImage">Upload image</button></details><div class="dialog-actions"><button class="btn btn-light" :disabled="busy||dirty" @click="visibility">{{form.hidden?'Restore question':'Hide question'}}</button><button class="btn btn-light" :disabled="busy||dirty||!history.length" @click="undo">Undo latest change</button></div><details class="mt-3"><summary>Correction history ({{history.length}})</summary><p v-for="h in history" :key="h.id">{{h.action}} · {{new Date(h.created_at*1000).toLocaleString()}}</p></details></div><aside><h3>Live preview</h3><QuestionContent :text="[form.passage,form.text].filter(Boolean).join('\n\n')" :images="previewImages.filter(i=>!i.option_key)"/><div class="review-option" v-for="o in form.options"><strong>{{o.key}}.</strong><QuestionContent :text="o.text" :images="previewImages.filter(i=>i.option_key===o.key)"/></div><p class="small muted">Answer: {{parsedAnswers}}</p><MathText :text="form.explanation"/><template v-if="form.ingestion_file_id"><h3 class="mt-4">Original source</h3><a :href="'/api/admin/ingestion/'+form.ingestion_file_id+'/source'" target="_blank" rel="noopener">Open PDF</a><label v-if="form.source_pages?.length>1">Source page<select class="form-select" v-model="sourcePage"><option v-for="page in form.source_pages" :value="page">{{page}}</option></select></label><img v-if="form.source_page" :src="'/api/admin/ingestion/'+form.ingestion_file_id+'/pages/'+sourcePage" class="source-page mt-3" alt="Original question source page"></template></aside></div></template></section></div></template>
